const c = await api.get("/customers", {});
const m = await api.get("/mails", {});
const customers = c.items || [];
const mails = m.items || [];
const delayed = customers.filter(x => x.order && x.order.status === "delayed").map(x => x.id);
const complaintCust = mails.filter(x => x.label === "complaint" && x.customer_id).map(x => x.customer_id);
const result = delayed.filter(id => complaintCust.includes(id));
return { totalCustomers: c.count, totalMails: m.count, delayed, complaintCust, result };
